package at.hausgarten.service;

import org.json.*;
import java.math.BigDecimal;

/** Local partial invoices keep original worked hours and expose only the exact unallocated remainder. */
public final class LocalBillingQuantityTests {
    static int checks;
    static void yes(boolean value){checks++;if(!value)throw new AssertionError("Local billing quantity check "+checks);}
    interface Task {void run()throws Exception;}
    static void denied(String code,Task task)throws Exception {try{task.run();}catch(PixelMcpWriteTools.Rejected expected){yes(expected.code.equals(code));return;}throw new AssertionError("Expected "+code);}
    static JSONObject state()throws Exception {JSONObject state=SyntheticBusinessData.profile("minimal").put("processing_engine",LocalAuthorityRules.ENGINE);JSONObject log=state.getJSONArray("worklogs").getJSONObject(0);log.put("hours",new BigDecimal("2.5")).put("billed",0);state.put("invoices",new JSONArray()).put("local_billing_sources",new JSONObject().put("formatVersion",1).put("by_invoice",new JSONObject()));return state;}
    static JSONObject log(JSONObject state)throws Exception{return state.getJSONArray("worklogs").getJSONObject(0);}
    static void issue(JSONObject state,String id,String quantity)throws Exception {String work=log(state).getString("id");JSONObject allocation=new JSONObject().put(work,quantity),invoice=new JSONObject().put("id",id).put("customer_id",log(state).getString("customer_id")).put("issued_at","2027-05-18T08:00:00Z").put("status","Gestellt").put("worklog_ids",new JSONArray().put(work)).put("positions",new JSONArray().put(new JSONObject().put("worklog_id",work).put("quantity",new BigDecimal(quantity)))).put("numbering_receipt",new JSONObject().put("authority",LocalAuthorityRules.ENGINE)).put("local_issue_request","qa_issue_"+id).put("local_source_allocations",new JSONObject(allocation.toString()));state.getJSONArray("invoices").put(invoice);state.getJSONObject("local_billing_sources").getJSONObject("by_invoice").put(id,allocation);}
    static JSONObject draft(JSONObject state,String quantity)throws Exception {return new JSONObject().put("id","qa_remaining_draft").put("customer_id",log(state).getString("customer_id")).put("status","Entwurf").put("positions",new JSONArray().put(new JSONObject().put("title","QA Restleistung").put("unit","h").put("quantity",new BigDecimal(quantity)).put("price",52).put("worklog_id",log(state).getString("id"))));}
    public static void main(String[] ignored)throws Exception {
        SyntheticBusinessData.verify();JSONObject state=state();JSONObject original=log(state);String saved=PixelMcpWriteTools.hash(original);yes(LocalBillingRules.state(original,state.getJSONArray("invoices"),state).getString("remaining_decimal").equals("2.5"));issue(state,"qa_partial_1","1");LocalBillingRules.validate(state,state.getJSONObject("local_billing_sources"));JSONObject quantities=LocalBillingRules.state(original,state.getJSONArray("invoices"),state);yes(quantities.getString("allocated_decimal").equals("1")&&quantities.getString("remaining_decimal").equals("1.5"));yes(PixelMcpBusinessTools.billing(original,state.getJSONArray("invoices"),state).equals("partially_invoiced"));JSONArray groups=BillingRules.groups(state.getJSONArray("worklogs"),state);JSONObject group=groups.getJSONObject(0),record=group.getJSONArray("work_records").getJSONObject(0);yes(record.getDouble("hours")==2.5&&record.getString("quantity_remaining_decimal").equals("1.5")&&group.getString("hours_decimal").equals("1.5")&&group.getDouble("hours")==1.5);yes(saved.equals(PixelMcpWriteTools.hash(original)));JSONObject report=PixelMcpBusinessTools.report(state.getJSONArray("worklogs"),state);yes(report.getInt("partially_invoiced")==1&&report.getInt("proven_invoiced")==0&&report.getDouble("hours")==2.5);
        JSONObject valid=draft(state,"1.5");InvoiceDraftRules.normalize(valid,null,state);yes(valid.getJSONObject("money_minor").getLong("gross_minor")==7800);denied("INVOICE_SOURCE_QUANTITY_EXCEEDED",()->InvoiceDraftRules.normalize(draft(state,"2.5"),null,state));issue(state,"qa_partial_2","1.5");LocalBillingRules.validate(state,state.getJSONObject("local_billing_sources"));yes(LocalBillingRules.state(original,state.getJSONArray("invoices"),state).getString("remaining_decimal").equals("0"));yes(BillingRules.groups(state.getJSONArray("worklogs"),state).length()==0&&PixelMcpBusinessTools.billing(original,state.getJSONArray("invoices"),state).equals("proven_invoiced"));yes(saved.equals(PixelMcpWriteTools.hash(original)));
        JSONObject legacy=state();legacy.remove("local_billing_sources");issueLegacy(legacy);yes(PixelMcpBusinessTools.billing(log(legacy),legacy.getJSONArray("invoices"),legacy).equals("proven_invoiced")&&BillingRules.groups(legacy.getJSONArray("worklogs"),legacy).length()==0);yes(LocalBillingRules.state(log(legacy),legacy.getJSONArray("invoices"),legacy)==null);
        JSONObject corrupt=state();issue(corrupt,"qa_bad_snapshot","1");corrupt.getJSONArray("invoices").getJSONObject(0).getJSONObject("local_source_allocations").put(log(corrupt).getString("id"),"2");denied("LOCAL_BILLING_SOURCE_REVIEW_REQUIRED",()->LocalBillingRules.validate(corrupt,corrupt.getJSONObject("local_billing_sources")));
        JSONObject over=state();issue(over,"qa_over_1","2");issue(over,"qa_over_2","1");denied("LOCAL_BILLING_SOURCE_REVIEW_REQUIRED",()->LocalBillingRules.validate(over,over.getJSONObject("local_billing_sources")));
        System.out.println("PASS "+checks+" local partial-source/remaining-draft/CAS-input/legacy/corruption checks;canonical historicalhours unchanged,synthetic JVM");
    }
    static void issueLegacy(JSONObject state)throws Exception {state.getJSONArray("invoices").put(new JSONObject().put("id","qa_legacy_invoice").put("status","Gestellt").put("issued_at","2026-10-18").put("worklog_ids",new JSONArray().put(log(state).getString("id"))));}
}
